import numpy as np, os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); I1=np.array(G['Demo pair 1 input']); O1=np.array(G['Demo pair 1 output'])
I2=np.array(G['Demo pair 2 input']); O2=np.array(G['Demo pair 2 output'])
def f(I,O,minor):
    H,W=I.shape; seen=np.zeros((H,W),bool); st=[]
    for r in range(H):
        for c in (0,W-1):
            if I[r][c]!=minor and not seen[r,c]: seen[r,c]=True; st.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if I[r][c]!=minor and not seen[r,c]: seen[r,c]=True; st.append((r,c))
    nbs=((1,0),(-1,0),(0,1),(0,-1))
    while st:
        r,c=st.pop()
        for dr,dc in nbs:
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W and I[rr][cc]!=minor and not seen[rr][cc]:
                seen[rr][cc]=True; st.append((rr,cc))
    K=(O!=I)
    pred=~seen
    acc=np.mean(((pred==K)&(I==np.unique(np.unique(I))[1]))+(~pred&K&(I==np.unique(np.unique(I))[0])))
    print('flood-barrier minor',minor,'acc',np.mean(pred==K))
for name,(I,O) in [('p1',(I1,O1)),('p2',(I2,O2))]:
    for v in np.unique(I): f(I,O,v)

