def comps4(I,val,bg):
    H,W=I.shape; seen=np.zeros((H,W),bool); out=[]
    for y in range(H):
        for x in range(W):
            if I[y][x]==val and not seen[y][x]:
                st=deque([(y,x)]); seen[y][x]=True; rs=cs=[]
                while st:
                    yy,xx=st.popleft(); rs.append(yy); cs.append(xx)
                    for dy,dx in ND:
