ND=((1,0),(-1,0),(0,1),(0,-1))
ND8=(ND+((-1,-1),(-1,1),(1,-1),(1,1)))
def comps(I, valset, D):
    H,W=I.shape
    seen=np.zeros((H,W),bool)
    out=[]
    for y in range(H):
        for x in range(W):
            if I[y][x] in valset and not seen[y][x]:
                q=deque([(y,x)]); seen[y][x]=True; size=0
                while q:
                    yy,xx=q.popleft(); size+=1
                    for dy,dx in D:
                        nnn,ncc=yy+dy,xx+dx
                        if 0<=nnn<H and 0<=ncc<W and not seen[nnn][ncc] and I[nnn][ncc] in valset:
                            seen[nnn][ncc]=True; q.append((nnn,ncc))
                out.append(size)
    return out
